'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const NS='http://www.w3.org/2000/svg';
const state={data:null,city:'karachi',api:false,view:'overview',unit:'C',hours:24,dateFrom:'',dateTo:'',datePreset:'outlook',filterAt:Date.now(),calendarMonth:'',draftStart:'',draftEnd:'',chatHistory:[],selected:null,filter:null,zoom:1,pan:{x:0,y:0},orbit:false,paused:typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches,loading:false};
const labels={weather:'Weather',air:'Air quality',forecast:'Stored ML forecast',evidence:'Model evidence',safety:'Safety guidance'};
const finite=v=>typeof v==='number'&&Number.isFinite(v);
const fmt=(v,d=1)=>finite(v)?v.toFixed(d):'—';
const temperature=v=>finite(v)?(state.unit==='F'?v*1.8+32:v):null;
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function date(value,options={}){if(!value||!Number.isFinite(new Date(value).getTime()))return 'Not available';return new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Karachi',day:'numeric',month:'short',hour:'numeric',minute:'2-digit',hour12:true,...options}).format(new Date(value));}
const clock=v=>date(v,{day:undefined,month:undefined});
const day=v=>date(v,{hour:undefined,minute:undefined,weekday:'short'});
const cityName=()=>state.data?.city?.name||'Karachi';
const networkRoot=network=>network.nodes.find(n=>n.group==='location')?.id||'karachi';
const safeURL=u=>typeof u==='string'&&/^https:\/\//.test(u)?escapeHTML(u):'#';
function weatherInfo(code,isDay=1){if(!finite(code))return ['◌','Conditions unavailable'];if(code===0)return isDay===0?['☾','Clear night']:['☀','Clear sky'];if(code<=2)return isDay===0?['☾','Partly cloudy']:['⛅','Partly cloudy'];if(code===3)return ['☁','Cloudy'];if([45,48].includes(code))return ['≋','Fog'];if(code>=95)return ['ϟ','Thunderstorms'];if([71,73,75,77,85,86].includes(code))return ['❄','Snow showers'];if(code>=51&&code<=67||code>=80&&code<=82)return ['☂','Rain'];return ['◌','Weather code '+code];}
function rowsForWindow(rows,hours){if(!rows?.length)return [];const start=new Date(rows[0].time_utc).getTime();return rows.filter(r=>new Date(r.time_utc).getTime()<=start+hours*3600000);}
function joinAir(weatherRows,airRows){const map=new Map((airRows||[]).map(r=>[new Date(r.time_utc).getTime(),r]));return weatherRows.map(r=>({...r,air:map.get(new Date(r.time_utc).getTime())||null}));}
function segments(rows,key,transform=v=>v){const out=[];let part=[];for(const row of rows){const t=new Date(row.time_utc).getTime(),v=transform(row[key]);if(Number.isFinite(t)&&finite(v))part.push([t,v]);else if(part.length){out.push(part);part=[];}}if(part.length)out.push(part);return out;}

function calendarDay(value){const t=new Date(value).getTime();return Number.isFinite(t)?new Date(t+5*3600000).toISOString().slice(0,10):'';}
function filterDates(rows,from='',to=''){return (rows||[]).filter(r=>{const d=calendarDay(r.time_utc);return d&&(!from||d>=from)&&(!to||d<=to);});}
function rollingRows(rows,now=Date.now()){return (rows||[]).filter(r=>{const t=new Date(r.time_utc).getTime();return t>=now-12*3600000&&t<=now;});}
function periodRows(rows){return state.datePreset==='12h'?rollingRows(rows,state.filterAt):filterDates(rows,state.dateFrom,state.dateTo);}
function selectedRows(rows){if(state.datePreset==='12h'){const feed=state.data&&[state.data.weather,state.data.air_quality].find(f=>f.hourly===rows);return rollingRows([...(feed?.recent_hourly||[]),...(rows||[])],state.filterAt).filter((r,i,all)=>all.findIndex(v=>new Date(v.time_utc).getTime()===new Date(r.time_utc).getTime())===i);}return state.dateFrom||state.dateTo?filterDates(rows,state.dateFrom,state.dateTo):rowsForWindow(rows,state.hours);}
function extreme(rows,key,max=true){return (rows||[]).filter(r=>finite(r[key])).reduce((best,r)=>!best||(max?r[key]>best[key]:r[key]<best[key])?r:best,null);}
function connectedLinks(links,id){return links.filter(l=>l.source===id||l.target===id);}
function forecastRows(weather){const boundary=weather.forecast_start_utc||weather.valid_at_utc;const t=new Date(boundary).getTime();const recent=(weather.recent_hourly||[]).filter(r=>new Date(r.time_utc).getTime()<t);const future=(weather.hourly||[]).filter(r=>new Date(r.time_utc).getTime()>t);const current={...weather.current,time_utc:boundary};return [...recent,current,...future].sort((a,b)=>new Date(a.time_utc)-new Date(b.time_utc));}


function presetDates(preset,now=new Date()){
 if(preset==='12h')return {from:calendarDay(new Date(now.getTime()-12*3600000)),to:calendarDay(now)};
 const to=calendarDay(now),start=new Date(to+'T00:00:00Z');
 if(preset==='7'||preset==='30')start.setUTCDate(start.getUTCDate()-Number(preset)+1);else return {from:'',to:''};
 return {from:start.toISOString().slice(0,10),to};
}
function dayNumber(value){return Math.round(new Date(value+'T00:00:00Z').getTime()/86400000);}
function dayString(value){return new Date(Number(value)*86400000).toISOString().slice(0,10);}
function calendarCells(month){const first=new Date(month+'T00:00:00Z'),offset=(first.getUTCDay()+6)%7,start=dayNumber(month)-offset;return Array.from({length:42},(_,i)=>dayString(start+i));}
function pickRange(start,end,value){if(!start||end)return {start:value,end:''};return value<start?{start:value,end:start}:{start,end:value};}
function dateLabel(value){return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T00:00:00Z'));}
function setDates(from,to,preset='custom'){state.dateFrom=from;state.dateTo=to;state.datePreset=preset;state.filterAt=Date.now();closeCalendar(false);render();}
function refreshCalendar(){
 const d=state.data,rows=[...(d.weather.recent_hourly||[]),...d.weather.hourly,...(d.air_quality.recent_hourly||[]),...d.air_quality.hourly,...(d.air_history.daily||d.air_history.monthly)],days=rows.map(r=>calendarDay(r.time_utc)).filter(Boolean).sort();
 $$('[data-date-preset]').forEach(b=>{const active=b.dataset.datePreset===state.datePreset;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
 const selected=periodRows(rows),label=state.datePreset==='12h'?'Last 12 hours':state.dateFrom?dateLabel(state.dateFrom)+' – '+dateLabel(state.dateTo):'Next '+state.hours+' hours';
 $('#date-status').textContent=label+(state.dateFrom&&!selected.length?' · No data':'')+' · PKT';
 $('#date-status').title=`Data available: ${days[0]||'—'} → ${days.at(-1)||'—'}. Only available records are shown; gaps may exist.`;
 $('#date-slicer').hidden=['network','evidence'].includes(state.view);
}
function closeCalendar(focus=true){$('#range-calendar').hidden=true;$('#custom-date-button').setAttribute('aria-expanded','false');if(focus)$('#custom-date-button').focus();}
function openCalendar(){
 if(!$('#range-calendar').hidden){closeCalendar();return;}
 state.draftStart=state.dateFrom;state.draftEnd=state.dateTo;state.calendarMonth=(state.dateFrom||calendarDay(new Date())).slice(0,7)+'-01';
 $('#range-calendar').hidden=false;$('#custom-date-button').setAttribute('aria-expanded','true');renderCalendar();
 const focus=$('[data-calendar-date="'+(state.draftStart||calendarDay(new Date()))+'"]');focus?.focus();
}
function moveCalendar(amount){const month=new Date(state.calendarMonth+'T00:00:00Z');month.setUTCMonth(month.getUTCMonth()+amount);state.calendarMonth=month.toISOString().slice(0,10);renderCalendar();}
function renderCalendar(){
 const month=new Date(state.calendarMonth+'T00:00:00Z'),year=month.getUTCFullYear(),today=calendarDay(new Date()),start=state.draftStart,end=state.draftEnd;
 const names=Array.from({length:12},(_,i)=>new Intl.DateTimeFormat('en-GB',{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2020,i,1))));
 const years=Array.from({length:Math.max(7,year-2019)},(_,i)=>2020+i);if(!years.includes(year))years.push(year);
 $('#calendar-heading').innerHTML=`<select id="calendar-month" aria-label="Calendar month">${names.map((n,i)=>`<option value="${i}" ${i===month.getUTCMonth()?'selected':''}>${n}</option>`).join('')}</select><select id="calendar-year" aria-label="Calendar year">${years.map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select>`;
 const cells=calendarCells(state.calendarMonth);
 $('#calendar-days').innerHTML=Array.from({length:6},(_,r)=>'<tr>'+cells.slice(r*7,r*7+7).map(value=>`<td class="${start&&end&&value>=start&&value<=end?'in-range':''}"><button type="button" data-calendar-date="${value}" class="${value.slice(0,7)!==state.calendarMonth.slice(0,7)?'other-month ':''}${value===start?'range-start ':''}${value===end?'range-end ':''}${value===today?'today':''}" aria-label="${dateLabel(value)}" aria-pressed="${value===start||value===end}" ${value===today?'aria-current="date"':''}>${Number(value.slice(8))}</button></td>`).join('')+'</tr>').join('');
 $('#calendar-hint').textContent=start&&!end?'Now choose the end date.':'Choose a start date, then an end date.';
 $('#calendar-selection').textContent=start?(dateLabel(start)+(end?' – '+dateLabel(end):' → …')):'No range selected';
 $('#calendar-apply').disabled=!start||!end;
 for(const id of ['calendar-month','calendar-year'])$('#'+id).addEventListener('change',()=>{state.calendarMonth=String($('#calendar-year').value)+'-'+String(Number($('#calendar-month').value)+1).padStart(2,'0')+'-01';renderCalendar();});
 $$('[data-calendar-date]').forEach(button=>{button.addEventListener('click',()=>{const chosen=pickRange(state.draftStart,state.draftEnd,button.dataset.calendarDate);state.draftStart=chosen.start;state.draftEnd=chosen.end;renderCalendar();$('[data-calendar-date="'+button.dataset.calendarDate+'"]').focus();});button.addEventListener('keydown',e=>{const step={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7}[e.key];if(!step)return;e.preventDefault();const target=dayString(dayNumber(button.dataset.calendarDate)+step);state.calendarMonth=target.slice(0,7)+'-01';renderCalendar();$('[data-calendar-date="'+target+'"]').focus();});});
}
function periodNote(){if(state.datePreset==='12h')return 'Last 12 hours · PKT';return state.dateFrom||state.dateTo?'Selected dates · PKT':'Next '+state.hours+' hours';}
function summarySentence(w,a){const rows=selectedRows(w.hourly),peak=extreme(rows,'heat_index_c'),air=extreme(selectedRows(a.hourly),'us_aqi');if(!rows.length)return 'No weather outlook is available in this date range. Explore the air archive for historical dates.';return `Feels-like heat reaches ${fmt(temperature(peak?.heat_index_c))}°${state.unit}${peak?' on '+day(peak.time_utc)+' at '+clock(peak.time_utc):''}; ${air?'air quality reaches US AQI '+fmt(air.us_aqi,0)+' in the same selected period.':'air-quality outlook is unavailable for these dates.'}`;}

const svgEl=(tag,attrs,parent)=>{const e=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));parent?.appendChild(e);return e;};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function badge(status){const names={live:'Recent model data',stored:'Stored snapshot',historical:'Historical data',cached_stale:'Cached · refresh failed',stale:'Source data is old',unavailable:'Unavailable',verified:'Verified'};return `<span class="source-badge ${escapeHTML(status)}"><i class="status-dot"></i>${escapeHTML(names[status]||status)}</span>`;}
function controls(){return `<div class="page-controls"><div class="segmented" aria-label="Forecast time range">${[24,48].map(h=>`<button data-hours="${h}" class="${!state.dateFrom&&!state.dateTo&&state.hours===h?'active':''}">${h} hours</button>`).join('')}</div><div class="segmented" aria-label="Temperature unit">${['C','F'].map(u=>`<button data-unit="${u}" class="${state.unit===u?'active':''}">°${u}</button>`).join('')}</div></div>`;}
const heading=(eyebrow,title,description,withControls=false)=>`<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2><p>${description}</p></div>${withControls?controls():''}</div>`;
const cardHead=(eyebrow,title,description='',status='')=>`<div class="card-header"><div><span class="eyebrow">${eyebrow}</span><h3>${title}</h3>${description?`<p>${description}</p>`:''}</div>${status?badge(status):''}</div>`;
const chartBox=id=>`<div class="chart" id="${id}"></div><div class="chart-tooltip" id="${id}-tooltip">Hover, tap or focus a point to see its value.</div>`;
const scale=()=>'<div class="aqi-scale" aria-label="US AQI bands from good to hazardous"><i></i><i></i><i></i><i></i><i></i><i></i></div>';

async function loadData(manual=false){
 if(state.loading)return;state.loading=true;$('#refresh-button').disabled=true;$('#city-select').disabled=true;
 try{
  let data;try{const r=await fetch('/api/dashboard?city='+encodeURIComponent(state.city),{signal:AbortSignal.timeout(15000),cache:'no-store'});if(!r.ok||!r.headers.get('content-type')?.includes('application/json'))throw Error();data=await r.json();state.api=true;}catch{const r=await fetch(state.city==='karachi'?'snapshot.json':'city-snapshots.json',{cache:'no-store'});if(!r.ok)throw Error('The API and saved snapshot are unavailable.');const saved=await r.json();data=state.city==='karachi'?saved:saved[state.city];if(!data||data.city?.id!==state.city)throw Error('No saved snapshot for this city.');state.api=false;}
  if(data.city?.id!==state.city)throw Error('The response belongs to a different city.');
  if(!data.weather||!data.air_quality||!data.network)throw Error('Dashboard data is incomplete. Rebuild the deployment package.');
  for(const feed of [data.weather,data.air_quality]){const age=(Date.now()-new Date(feed.valid_at_utc).getTime())/1000;if(feed.status==='live'&&(!Number.isFinite(age)||age>10800||age< -3600))feed.status='stale';} const forecastAge=(Date.now()-new Date(data.freshness.collected_at_utc).getTime())/1000;data.fresh=Boolean(data.verified&&forecastAge>=0&&forecastAge<=10800);state.data=data;state.lastLoad=Date.now();if(state.datePreset==='12h'){state.filterAt=Date.now();const period=presetDates('12h');state.dateFrom=period.from;state.dateTo=period.to;}updateHeader();render();
  if(manual)toast(state.api?'Dashboard checked. Source timestamps show when the cache last refreshed.':'API unavailable. Showing the saved snapshot.');
 }catch(e){if(!state.data)$('#content-view').innerHTML=`<div class="loading-state"><h2>Unable to load the dashboard</h2><p>${escapeHTML(e.message)}</p></div>`;toast(e.message);}
 finally{state.loading=false;$('#refresh-button').disabled=false;$('#city-select').disabled=false;}
}
function updateHeader(){
 const d=state.data,w=d.weather,a=d.air_quality,c=w.current,wr=selectedRows(w.hourly),ar=selectedRows(a.hourly),peak=extreme(wr,'heat_index_c');
 $('#city-select').innerHTML=(d.cities||[]).map(c=>`<option value="${escapeHTML(c.id)}" ${c.id===state.city?'selected':''}>${escapeHTML(c.name)}</option>`).join('');
 $('#city-title').textContent=cityName()+' Pulse';$('#city-location').textContent=cityName()+', Pakistan';document.title='HeatSafe Pakistan · '+cityName()+' Pulse';$('.pulse-panel').setAttribute('aria-label',cityName()+' Pulse key indicators');$('#network').setAttribute('aria-label',cityName()+' data network');
 $('#connection-label').textContent=!state.api?'Saved snapshot':w.status==='live'&&a.status==='live'?'Weather + AQI connected':'Source data limited';
 $('#connection-dot').classList.toggle('stale',!state.api||w.status!=='live'||a.status!=='live');
 const pulls=[w.fetched_at_utc,a.fetched_at_utc].filter(Boolean).map(v=>new Date(v).getTime());
 $('#last-pull').textContent='Last source pull: '+(pulls.length?date(Math.max(...pulls))+' PKT':'Unavailable');
 $('.last-pull').title=`Weather: ${date(w.fetched_at_utc)} PKT\nAir: ${date(a.fetched_at_utc)} PKT\nModel estimates, not on-site sensors.`;
 let title='City now',kpis=[['☀','TEMPERATURE',temperature(c.temperature_c),'°'+state.unit,'Latest source value'],['◈','FEELS LIKE',temperature(c.heat_index_c),'°'+state.unit,'Calculated heat index'],['≋','US AQI',a.current.us_aqi,'',a.current.aqi_category],['◌','HUMIDITY',c.humidity_pct,'%','Latest source value'],['↝','WIND',c.wind_speed_ms,'m/s','At 10 metres']];
 if(state.view==='forecast'){title='Planning outlook';kpis=[['🔥','PEAK FEELS LIKE',temperature(peak?.heat_index_c),'°'+state.unit,peak?clock(peak.time_utc)+' PKT':'No selected data'],['☀','HIGH',temperature(extreme(wr,'temperature_c')?.temperature_c),'°'+state.unit,periodNote()],['☾','LOW',temperature(extreme(wr,'temperature_c',false)?.temperature_c),'°'+state.unit,periodNote()],['💧','PEAK HUMIDITY',extreme(wr,'humidity_pct')?.humidity_pct,'%','Selected outlook'],['◷','TIME POINTS',wr.length,'','Available hourly values']];}
 if(state.view==='air'){const archive=state.datePreset!=='12h'&&!ar.length&&(state.dateFrom||state.dateTo),pollutantRows=archive?filterDates(d.air_history.daily||[],state.dateFrom,state.dateTo):ar;title=archive?'Air archive':'Air outlook';kpis=[['≋','PEAK US AQI',extreme(ar,'us_aqi')?.us_aqi,'',periodNote()],...['pm2_5','pm10','nitrogen_dioxide','ozone'].map((k,i)=>['◌',['PEAK PM2.5','PEAK PM10','PEAK NO₂','PEAK O₃'][i],extreme(pollutantRows,k)?.[k],'µg/m³',archive?'Peak daily mean':'Selected forecast'])];}
 if(state.view==='network'){title='Connected evidence';kpis=[['◎','NODES',d.network.nodes.length,'','From backend payload'],['⌁','LINKS',d.network.links.length,'','Select a node to trace'],['☀','WEATHER',d.network.nodes.filter(n=>n.group==='weather').length,'','Connected signals'],['≋','AIR SIGNALS',d.network.nodes.filter(n=>n.group==='air').length,'','Available signals'],['▧','GUIDANCE',d.sources.length,'','Official sources']];}
 if(state.view==='evidence'){title='Source integrity';kpis=[['▧','SOURCES',d.sources.length,'','Official safety knowledge'],['↔','MODEL ERROR',d.metrics.test_model_mae_c,'°C','Mean absolute error'],['◈','TEST R²',d.metrics.test_model_r2,'','Held-out evaluation'],['◷','TEST HOURS',d.metrics.test_rows,'','Historical evaluation'],['↻','API CACHE',15,'min','Per Python instance']];}
 $('#panel-name').textContent=title;
 $('#pulse-kpis').innerHTML=kpis.map(([icon,label,value,unit,note])=>`<div class="pulse-kpi"><div class="kpi-label"><span>${icon}</span>${label}</div><strong>${fmt(value,label.includes('AQI')||unit==='%'||unit===''&&label!=='TEST R²'||unit==='min'?0:label==='TEST R²'?3:1)}<small>${unit}</small></strong><div class="kpi-note" title="${escapeHTML(note)}">${escapeHTML(note)}</div></div>`).join('');
 refreshCalendar();
}
function showView(view,scroll=true){state.view=view;render();if(scroll)window.scrollTo({top:0,behavior:'instant'});}
function render(){
 if(!state.data)return;updateHeader();$$('.view-tab').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-current',b.dataset.view===state.view?'page':'false');});
 $('#network-view').hidden=state.view!=='network';$('#content-view').hidden=state.view==='network';
 if(state.view==='network'){buildNetwork();return;}
 $('#content-view').innerHTML=({overview:overviewView,forecast:forecastView,air:airView,evidence:evidenceView}[state.view]||overviewView)();
 $$('[data-view-link]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.viewLink)));
 $$('[data-hours]').forEach(b=>b.addEventListener('click',()=>{state.hours=Number(b.dataset.hours);state.datePreset='outlook';state.dateFrom='';state.dateTo='';closeCalendar(false);render();}));
 $$('[data-unit]').forEach(b=>b.addEventListener('click',()=>{state.unit=b.dataset.unit;updateHeader();render();}));
 drawViewCharts();
}
function liveNotice(){const d=state.data;const issues=[];if(!state.api)issues.push('Saved snapshot: the Python API is unavailable.');if(d.weather.status!=='live')issues.push(d.weather.note);if(d.air_quality.status!=='live')issues.push(d.air_quality.note);else if(!finite(d.air_quality.current.us_aqi))issues.push('The current AQI index is unavailable; valid pollutant values may still be shown.');return issues.length?`<div class="callout"><span>◷</span><p>${issues.map(escapeHTML).join(' ')}</p></div>`:'';}
function weatherCard(){const w=state.data.weather;return `<article class="card panel wide">${cardHead('FORECAST TIMELINE','See where the prediction begins','Recent modeled conditions → future weather outlook · °'+state.unit,w.status)}${chartBox('weather-chart')}<div class="chart-legend"><span><i style="background:var(--weather)"></i>Air temperature</span><span><i style="background:var(--forecast)"></i>Calculated heat index</span><span>┆ Vertical line = forecast begins · dashed = future</span></div><div class="chart-note">Boundary: ${date(w.forecast_start_utc||w.valid_at_utc)} PKT, the source’s model-valid time. Left-side values, when available, are recent model estimates—not sensor observations. The shaded right side is the weather-model outlook; the saved ML result is separate below.</div></article>`;}
function airCard(){const a=state.data.air_quality;return `<article class="card panel">${cardHead('AIR QUALITY','A clearer view of the air','US AQI · CAMS model estimate',a.status)}<div class="card-stat">${fmt(a.current.us_aqi,0)}<small>US AQI</small></div><div class="aqi-category">${escapeHTML(a.current.aqi_category)}</div>${scale()}<p class="chart-note">📍 ${finite(a.current.us_aqi)?'Current band: '+escapeHTML(a.current.aqi_category)+' · '+fmt(a.current.us_aqi,0)+' US AQI':'No current AQI available'} · chart below follows the selected period.</p>${chartBox('aqi-chart')}<div class="chart-note">${a.current.us_aqi===null?'No current AQI is available. Historical concentrations are shown separately.':'Source valid at '+date(a.valid_at_utc)+' PKT. US AQI is an index; pollutant concentrations use µg/m³.'}</div></article>`;}
function weatherTable(){const rows=selectedRows(state.data.weather.hourly).filter((_,i)=>i%3===0),peak=extreme(rows,'heat_index_c'),cool=extreme(rows,'heat_index_c',false);const values=rows.map(r=>r.heat_index_c).filter(finite),min=values.length?Math.min(...values):0,max=values.length?Math.max(...values):0;return `<article class="card panel wide">${cardHead('HOURLY PLANNING STRIP','Your day, at a glance','Every third available hour · bar length compares feels-like heat within this period')}<div class="hour-flow">${rows.length?rows.map((r,i)=>{const [icon,description]=weatherInfo(r.weather_code,r.is_day);return `<div class="hour-row" style="--delay:${Math.min(i,10)*35}ms"><div class="hour-time"><strong>${clock(r.time_utc)}</strong><small>${day(r.time_utc)}</small></div><span class="hour-weather" title="${escapeHTML(description)}" aria-label="${escapeHTML(description)}">${icon}</span><div class="hour-track"><i style="--fill:${finite(r.heat_index_c)?20+80*(r.heat_index_c-min)/Math.max(1,max-min):0}%"></i><span>${r===peak?'🔥 Warmest':r===cool?'🌙 Cooler':'Feels like'} ${fmt(temperature(r.heat_index_c))}°${state.unit}</span></div><span class="hour-humidity">💧 ${fmt(r.humidity_pct,0)}%</span></div>`;}).join(''):'<p class="chart-empty">No hourly outlook in the selected dates.</p>'}</div></article>`;}
function overviewView(){const d=state.data,w=d.weather,a=d.air_quality,rows=selectedRows(w.hourly),peak=extreme(rows,'heat_index_c'),cool=extreme(rows,'heat_index_c',false),[icon,description]=weatherInfo(w.current.weather_code,w.current.is_day);return `<div class="city-stage"><div class="city-copy"><span class="eyebrow">${escapeHTML(cityName().toUpperCase())} · WEATHER & AIR TOGETHER</span><h2>Your city.<br><span>A clearer day.</span></h2><p class="main-insight">${escapeHTML(summarySentence(w,a))}</p><p class="stage-caption">${escapeHTML(periodNote())} · model-based outlook</p><div class="stage-actions"><button class="primary-action" data-view-link="forecast">Plan your hours ↗</button><button class="secondary-action" data-view-link="air">Explore the air ≋</button></div>${controls()}</div><div class="city-orbit" aria-label="Current weather: ${escapeHTML(description)}"><div class="orbit-ring ring-one"></div><div class="orbit-ring ring-two"></div><div class="orbit-core"><span class="weather-symbol">${icon}</span><span class="eyebrow">LATEST SOURCE CONDITIONS</span><strong>${fmt(temperature(w.current.temperature_c))}<small>°${state.unit}</small></strong><span>${escapeHTML(description)}</span><small>${date(w.valid_at_utc)} PKT</small></div><div class="orbit-tag tag-air">≋ Air now <strong>${fmt(a.current.us_aqi,0)} US AQI</strong><small>${escapeHTML(a.current.aqi_category)} · ${date(a.valid_at_utc)}</small></div><div class="orbit-tag tag-heat">◈ Feels like <strong>${fmt(temperature(w.current.heat_index_c))}°${state.unit}</strong><small>Calculated from temperature + humidity</small></div></div><div class="city-events"><button data-view-link="forecast"><span>🔥</span><div><small>WARMEST FEELING</small><strong>${peak?day(peak.time_utc)+' · '+clock(peak.time_utc):'No selected data'}</strong></div><b>${fmt(temperature(peak?.heat_index_c))}°</b></button><button data-view-link="forecast"><span>🌙</span><div><small>COOLER WINDOW</small><strong>${cool?day(cool.time_utc)+' · '+clock(cool.time_utc):'No selected data'}</strong></div><b>${fmt(temperature(cool?.heat_index_c))}°</b></button><button data-view-link="network"><span>⌘</span><div><small>FOLLOW THE EVIDENCE</small><strong>Explore connected city signals</strong></div><b>↗</b></button></div></div>${liveNotice()}`;}
function modelCard(){const d=state.data,f=d.forecast;if(f.available===false)return `<article class="card panel wide">${cardHead('YOUR PROJECT’S TRAINED MODEL','Stored ML prediction unavailable')}<p class="chart-note">No stored live ML prediction is bundled for ${escapeHTML(cityName())}. The weather-model outlook above is available; Karachi’s ML prediction is not applied to this city.</p></article>`;if((state.dateFrom||state.dateTo)&&!filterDates([{time_utc:f.target_time_utc}],state.dateFrom,state.dateTo).length)return '<div class="callout wide"><p>No stored ML target falls in the selected dates.</p></div>';return `<article class="card panel wide">${cardHead('YOUR PROJECT’S TRAINED MODEL','Stored 24-hour ML prediction','A separate result from your original pipeline',d.fresh?'verified':'stale')}<div class="model-card"><div><div class="card-stat">${fmt(temperature(f.model_prediction_c))}<small>°${state.unit}</small></div><div class="card-stat-note">${escapeHTML(f.model_risk_category)}</div></div><div class="model-explanation"><p>Target: <strong>${date(f.target_time_utc)} PKT</strong><br>Collected: ${date(d.freshness.collected_at_utc)} PKT<br>Historical interval: ${fmt(temperature(f.interval_lower_c))}–${fmt(temperature(f.interval_upper_c))}°${state.unit}</p><p>The live line above uses a heat-index formula. This ML point comes from the saved database. The website does not rerun the model; historical interval coverage is not guaranteed for live inputs.</p></div></div></article>`;}
function forecastView(){return heading('AHEAD OF THE HEAT','Find your window.','A marked prediction timeline and an hourly planning strip. All times use Pakistan time.',true)+liveNotice()+`<div class="dashboard-grid">${weatherCard()}${weatherTable()}${modelCard()}</div>`;}
function airView(){const a=state.data.air_quality,rows=selectedRows(a.hourly),peak=extreme(rows,'pm2_5'),low=extreme(rows,'pm2_5',false),history=state.dateFrom||state.dateTo;return heading('BREATHE WITH MORE CONTEXT','The air, made visible.','AQI tells the overall story. Particle and gas concentrations reveal the detail.',true)+liveNotice()+`<div class="dashboard-grid">${airCard()}<article class="card panel">${cardHead('LATEST POLLUTANT PROFILE','What is in the air?','Model concentrations · not a percentage breakdown',a.status)}<div class="air-motion" aria-hidden="true">${Array.from({length:14},(_,i)=>`<i style="--i:${i}"></i>`).join('')}<span>≋</span></div><div class="pollutant-profile">${[['PM2.5','pm2_5','Fine particles'],['PM10','pm10','Includes fine particles'],['NO₂','nitrogen_dioxide','Nitrogen dioxide'],['O₃','ozone','Ozone']].map(([name,key,note])=>`<div><span><b>${name}</b><small>${note}</small></span><strong>${fmt(a.current[key])}<small> µg/m³</small></strong></div>`).join('')}</div><p class="chart-note">${date(a.valid_at_utc)} PKT. Floating dots illustrate airborne particles; their size, speed and count do not measure pollution. Gases are shown numerically, not as particles.</p></article><article class="card panel wide">${cardHead('PARTICULATE MATTER','Small particles, explained','PM2.5 & PM10 outlook · µg/m³')}${chartBox('particles-chart')}<div class="chart-legend"><span><i style="background:var(--air)"></i>PM2.5 · fine particles</span><span><i style="background:var(--safety)"></i>PM10 · particles up to 10 µm</span></div><div class="particle-explainer"><span>🔎</span><p><strong>What this means:</strong> A higher line means more particle mass in each cubic metre of air. PM2.5 measures fine particles up to 2.5 micrometres; PM10 includes particles up to 10 micrometres, including PM2.5. Do not add these two values together. These concentrations are not AQI scores.</p></div><p class="chart-note">${peak?`📍 Selected outlook: PM2.5 ranges from ${fmt(low.pm2_5)} to ${fmt(peak.pm2_5)} µg/m³, peaking ${day(peak.time_utc)} at ${clock(peak.time_utc)} PKT.`:'No particulate outlook is available for these dates.'} <a href="https://www.epa.gov/pm-pollution/particulate-matter-pm-basics" target="_blank" rel="noopener noreferrer">About particles ↗</a></p></article><article class="card panel wide">${cardHead('YOUR EXISTING DATASET','The longer view',history?'Daily mean in selected dates · µg/m³':'Monthly mean · latest 12 archive months · µg/m³','historical')}${chartBox('history-chart')}<div class="chart-note">${state.data.city?.id!=='karachi'?'No historical air-quality archive is bundled for '+escapeHTML(cityName())+'. The outlook above uses this city’s API coordinates.':'Read-only CAMS archive from cleaned.cams_air_quality. Historical particle concentrations are separate from today’s AQI. Calendar selection uses Pakistan days; missing dates remain empty.'}</div></article></div>`;}
function evidenceView(){const d=state.data,w=d.weather,a=d.air_quality;const rows=[['Weather data valid at',date(w.valid_at_utc)+' PKT'],['Weather last source pull',date(w.fetched_at_utc)+' PKT'],['Air data valid at',date(a.valid_at_utc)+' PKT'],['Air last source pull',date(a.fetched_at_utc)+' PKT'],['Last backend response',date(d.server_response_at_utc)+' PKT'],['Page checks','Every 5 minutes while open'],['Upstream API cache','15 minutes per Python instance'],['Scheduled Prefect job on Vercel','Not running'],['Bundled DuckDB updates','Manual rebuild and redeploy'],['Stored ML input collected',date(d.freshness.collected_at_utc)+' PKT']];return heading('THE EVIDENCE BEHIND THE PICTURE','Every number has a story.','Source dates, update behavior and model evaluation—without the guesswork.')+`<div class="callout"><span>◎</span><p><strong>Where the database runs.</strong> ${state.data.storage?'DuckDB runs inside the Python backend with a read-only bundled file. It does not contact your computer.':'In local mode DuckDB reads the project file on your computer; on Vercel it reads the bundled deployment copy.'} Live weather/AQI requests do not write into that database.</p></div><div class="dashboard-grid"><article class="card panel">${cardHead('UPDATE STATUS','What updates, and when?')}<dl class="update-list">${rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${escapeHTML(v)}</dd></div>`).join('')}</dl><p class="chart-note">No background pipeline or cloud cron is enabled. New Vercel instances have their own caches and can fetch sooner. When nobody requests the site, nothing refreshes. The original Prefect configuration is hourly, but it requires a running worker outside this deployment.</p></article>${finite(d.metrics.test_model_mae_c)?`<article class="card panel">${cardHead('MODEL EVALUATION','Measured, not assumed','Held-out 2025 test data')}<div class="mini-stats"><div><strong>${fmt(d.metrics.test_model_mae_c,2)}°C</strong><span>Mean absolute error</span></div><div><strong>${fmt(d.metrics.test_model_r2,3)}</strong><span>Test R²</span></div><div><strong>${finite(d.metrics.test_rows)?d.metrics.test_rows.toLocaleString():'—'}</strong><span>Test hours</span></div></div><p class="card-description" style="margin-top:20px">The model is compared against same-hour previous-day persistence. Its baseline test error is ${fmt(d.metrics.test_baseline_mae_c,3)}°C. Risk-category accuracy is ${fmt(finite(d.risk_metrics.accuracy)?d.risk_metrics.accuracy*100:null,1)}%, derived from heat index rather than observed worker illness.</p><p class="chart-note">Weather sources are model estimates, not personal exposure or occupational WBGT measurements. The AI assistant explains city data and retrieved official evidence; its answers include sources.</p><a class="card-link" href="https://open-meteo.com/en/docs" target="_blank" rel="noopener noreferrer">Weather API documentation ↗</a><br><a class="card-link" href="https://open-meteo.com/en/docs/air-quality-api" target="_blank" rel="noopener noreferrer">Air-quality API documentation ↗</a></article>`:`<article class="card panel">${cardHead('MODEL EVALUATION','No city-specific evaluation bundled')}<p class="chart-note">No trained-model evaluation is available here for ${escapeHTML(cityName())}. The weather and air charts show provider model estimates, not a HeatSafe ML result.</p></article>`}</div><h3 class="page-section-title">Official safety knowledge</h3><div class="source-list">${d.sources.map((s,i)=>`<article class="source-card panel"><span class="eyebrow">SOURCE 0${i+1}</span><h3>${escapeHTML(s.publisher)}</h3><p>${escapeHTML(s.title)}</p><a href="${safeURL(s.url)}" target="_blank" rel="noopener noreferrer">Read the official guidance ↗</a></article>`).join('')}</div>`;}

let chartSequence=0;
function drawChart(id,rows,series,{area=false,unit='',monthly=false,zero=false,forecastStart=null}={}){
 const container=$('#'+id);if(!container)return;const validRows=(rows||[]).filter(r=>Number.isFinite(new Date(r.time_utc).getTime()));const prepared=series.map(s=>({...s,parts:segments(validRows,s.key,s.transform||((v)=>v))}));const values=prepared.flatMap(s=>s.parts.flatMap(p=>p.map(x=>x[1])));
 if(!validRows.length||!values.length){container.innerHTML='<div class="chart-empty">No values available for this period.<br>See the source status and historical data below.</div>';$('#'+id+'-tooltip').textContent='Missing values are not plotted as zero.';return;}
 const W=660,H=215,L=42,R=18,T=53,B=32,times=validRows.map(r=>new Date(r.time_utc).getTime()),start=Math.min(...times),end=Math.max(...times);let min=zero?0:Math.min(...values),max=Math.max(...values);const pad=Math.max((max-min)*.15,unit==='%'?3:1);if(!zero)min-=pad;max+=pad;const x=t=>L+(t-start)/Math.max(1,end-start)*(W-L-R),y=v=>H-B-(v-min)/(max-min)*(H-T-B);
 const svg=svgEl('svg',{viewBox:`0 0 ${W} ${H}`,role:'group','aria-label':series.map(s=>s.label).join(' and ')+' chart'},container);svgEl('title',{},svg).textContent=series.map(s=>s.label).join(' and ')+', '+unit;const defs=svgEl('defs',{},svg);
 for(let i=0;i<=4;i++){const v=min+(max-min)*i/4;svgEl('line',{x1:L,x2:W-R,y1:y(v),y2:y(v),class:'chart-grid'},svg);svgEl('text',{x:L-7,y:y(v)+3,'text-anchor':'end',class:'chart-label'},svg).textContent=fmt(v,0)+(unit==='°'?'°':'');}
 for(let i=0;i<Math.min(5,validRows.length);i++){const row=validRows[Math.round((validRows.length-1)*i/Math.max(1,Math.min(5,validRows.length)-1))];const label=monthly?date(row.time_utc,{day:undefined,hour:undefined,minute:undefined}):clock(row.time_utc);svgEl('text',{x:x(new Date(row.time_utc).getTime()),y:H-8,'text-anchor':i===0?'start':i===4?'end':'middle',class:'chart-label'},svg).textContent=label;}

 const boundary=new Date(forecastStart).getTime();
 if(forecastStart&&Number.isFinite(boundary)&&boundary<=end){const bx=x(Math.max(start,boundary));svgEl('rect',{x:bx,y:T,width:W-R-bx,height:H-B-T,fill:'var(--forecast)',opacity:'.07'},svg);svgEl('line',{x1:bx,x2:bx,y1:24,y2:H-B,stroke:'var(--forecast)','stroke-width':2,'stroke-dasharray':'4 4',class:'forecast-boundary'},svg);svgEl('text',{x:Math.min(W-220,bx+8),y:17,class:'event-label'},svg).textContent=boundary<start?'↗ Forecast already in progress':'↗ Prediction begins · '+clock(boundary);}
prepared.forEach(s=>{const color=getComputedStyle(document.documentElement).getPropertyValue(s.color).trim();const gradientId='fill-'+(++chartSequence),gradient=svgEl('linearGradient',{id:gradientId,x1:0,x2:0,y1:0,y2:1},defs);svgEl('stop',{offset:'0%', 'stop-color':color,'stop-opacity':'.25'},gradient);svgEl('stop',{offset:'100%','stop-color':color,'stop-opacity':'.01'},gradient);
  s.parts.forEach(part=>{const path=part.map(([t,v],i)=>`${i?'L':'M'}${x(t)},${y(v)}`).join(' ');if(area)svgEl('path',{d:path+` L${x(part.at(-1)[0])},${H-B} L${x(part[0][0])},${H-B}Z`,fill:`url(#${gradientId})`},svg);if(forecastStart){const past=part.filter(([t])=>t<=boundary),future=part.filter(([t])=>t>=boundary);const left=part.filter(([t])=>t<boundary).at(-1),right=part.find(([t])=>t>boundary);if(left&&right&&!part.some(([t])=>t===boundary)){const v=left[1]+(right[1]-left[1])*(boundary-left[0])/(right[0]-left[0]);past.push([boundary,v]);future.unshift([boundary,v]);}for(const [points,dashed] of [[past,false],[future,true]])if(points.length)svgEl('path',{d:points.map(([t,v],i)=>`${i?'L':'M'}${x(t)},${y(v)}`).join(' '),fill:'none',stroke:color,'stroke-width':2,'stroke-dasharray':dashed?'6 4':'none'},svg);}else svgEl('path',{d:path,fill:'none',stroke:color,'stroke-width':'2'},svg);
   part.forEach(([t,v],i)=>{if(i%3&&i!==part.length-1)return;const dot=svgEl('circle',{cx:x(t),cy:y(v),r:5,fill:color,'fill-opacity':'.65',tabindex:'0',role:'button','aria-label':`${date(t)} PKT, ${s.label}: ${fmt(v)} ${unit}`},svg);const show=()=>{$('#'+id+'-tooltip').textContent=`${date(t)} PKT · ${s.label}: ${fmt(v)} ${unit}`;dot.setAttribute('fill-opacity','1');};dot.addEventListener('mouseenter',show);dot.addEventListener('focus',show);dot.addEventListener('click',show);dot.addEventListener('mouseleave',()=>dot.setAttribute('fill-opacity','.65'));});});

 });
 const primary=prepared.at(-1),points=primary.parts.flat().filter(([t])=>!forecastStart||t>=boundary),hi=points.reduce((b,p)=>!b||p[1]>b[1]?p:b,null),lo=points.reduce((b,p)=>!b||p[1]<b[1]?p:b,null);
 const markers=hi&&lo&&(hi[0]!==lo[0])?[[hi,forecastStart?'🔥 Forecast peak':'▲ Peak'],[lo,forecastStart?'🌙 Forecast low':'▼ Low']]:hi?[[hi,'● Steady']]:[];
 markers.forEach(([point,label],i)=>{const [t,v]=point,px=x(t),py=y(v),tx=Math.max(L+4,Math.min(W-190,px-55)),ty=30+i*17;svgEl('line',{x1:px,x2:px,y1:ty+5,y2:py,stroke:'var(--muted)','stroke-dasharray':'2 3',opacity:'.6'},svg);svgEl('circle',{cx:px,cy:py,r:4,fill:'var(--text)',stroke:'var(--panel)', 'stroke-width':2},svg);svgEl('text',{x:tx,y:ty,class:'event-label'},svg).textContent=`${label} ${fmt(v)} ${unit} · ${monthly?day(t):clock(t)}`;});
 const note=document.createElement('p');note.className='chart-summary';note.textContent=markers.map(([[t,v],label])=>`${label}: ${primary.label} ${fmt(v)} ${unit}, ${date(t)} PKT`).join(' · ');container.appendChild(note);
}
function drawViewCharts(){const d=state.data,allWeather=forecastRows(d.weather),cutoff=new Date(d.weather.forecast_start_utc||d.weather.valid_at_utc).getTime()+state.hours*3600000,w=state.dateFrom||state.dateTo?periodRows(allWeather):allWeather.filter(r=>new Date(r.time_utc).getTime()<=cutoff),a=selectedRows(d.air_quality.hourly);drawChart('weather-chart',w,[{key:'temperature_c',label:'Temperature',color:'--weather',transform:temperature},{key:'heat_index_c',label:'Heat index',color:'--forecast',transform:temperature}],{unit:'°'+state.unit,forecastStart:d.weather.forecast_start_utc||d.weather.valid_at_utc});drawChart('aqi-chart',a,[{key:'us_aqi',label:'US AQI',color:'--air'}],{area:true,unit:'US AQI',zero:true});drawChart('particles-chart',a,[{key:'pm2_5',label:'PM2.5',color:'--air'},{key:'pm10',label:'PM10',color:'--safety'}],{unit:'µg/m³',zero:true});const custom=state.dateFrom||state.dateTo;drawChart('history-chart',custom?filterDates(d.air_history.daily||[],state.dateFrom,state.dateTo):d.air_history.monthly,[{key:'pm2_5',label:'Historical PM2.5 '+(custom?'daily':'monthly')+' mean',color:'--air'}],{area:true,unit:'µg/m³',monthly:true,zero:true});}
function nodeValue(n){if(n.id==='mae')return fmt(n.value,2)+' °C';return typeof n.value==='string'?n.value:finite(n.value)?fmt(n.unit==='°C'?temperature(n.value):n.value,n.id==='aqi'?0:n.id==='r2'?3:1)+(n.unit?' '+(n.unit==='°C'?'°'+state.unit:n.unit):''):'';}
function graphPositions(network,orbit=false){const groups=network.nodes.filter(n=>n.parent===networkRoot(network));return network.nodes.map(n=>{if(n.id===networkRoot(network))return {...n,x:705,y:410,r:30};const g=groups.findIndex(g=>g.id===(n.parent===networkRoot(network)?n.id:n.parent));const angle=-Math.PI*.78+Math.max(0,g)*Math.PI*2/Math.max(1,groups.length);if(n.parent===networkRoot(network))return {...n,x:705+Math.cos(angle)*185,y:410+Math.sin(angle)*185,r:16};const siblings=network.nodes.filter(s=>s.parent===n.parent),i=siblings.findIndex(s=>s.id===n.id);const spread=(i-(siblings.length-1)/2)*.24;const distance=orbit?285:280+(i%2)*22;return {...n,x:705+Math.cos(angle+spread)*distance,y:410+Math.sin(angle+spread)*distance,r:8};});}
function buildNetwork(){
 const graph=state.data.network,points=graphPositions(graph,state.orbit),edgeGroup=$('#edges'),nodeGroup=$('#nodes');edgeGroup.replaceChildren();nodeGroup.replaceChildren();
 [135,235,335].forEach(r=>svgEl('circle',{cx:705,cy:410,r,fill:'none',stroke:'var(--border)','stroke-opacity':'.4'},edgeGroup));
 graph.links.forEach(link=>{const a=points.find(n=>n.id===link.source),b=points.find(n=>n.id===link.target);if(a&&b)svgEl('path',{d:`M${a.x},${a.y} Q${(a.x+b.x)/2+10},${(a.y+b.y)/2-10} ${b.x},${b.y}`,class:'graph-edge','data-group':b.group,'data-source':link.source,'data-target':link.target},edgeGroup);});
 points.forEach(n=>{const root=n.id===networkRoot(graph),color=root?'var(--gold)':`var(--${n.group})`;const g=svgEl('g',{class:'graph-node'+(state.selected===n.id?' selected':''),transform:`translate(${n.x} ${n.y})`,style:`--node-color:${color}`,tabindex:'0',role:'button','aria-label':`Explore ${n.label}${nodeValue(n)?': '+nodeValue(n):''}`,'data-id':n.id,'data-group':n.group},nodeGroup);svgEl('circle',{r:n.r+16,filter:'url(#glow)',class:'node-halo'},g);svgEl('circle',{r:n.r,fill:'var(--panel2)',class:'node-circle'},g);svgEl('circle',{r:n.r*.45,fill:color,opacity:'.65'},g);const left=n.x<650,tx=left?-n.r-11:n.r+11;const text=svgEl('text',{x:root?0:tx,y:root?53:-2,'text-anchor':root?'middle':left?'end':'start',class:root?'core-label':'node-label'},g);text.textContent=n.label;const value=svgEl('text',{x:root?0:tx,y:root?70:13,'text-anchor':root?'middle':left?'end':'start',class:root?'core-note':'node-value'},g);value.textContent=root?'CONNECTED CITY DATA':nodeValue(n);const select=()=>showNode(n.id);g.addEventListener('click',select);g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}});});
 const groups=graph.nodes.filter(n=>n.parent===networkRoot(graph));$('#legend').innerHTML='<span class="eyebrow">FOCUS YOUR VIEW</span>'+groups.map(n=>`<button class="legend-item" data-filter="${n.group}" aria-pressed="${state.filter===n.group}" style="--node-color:var(--${n.group})"><i></i>${escapeHTML(n.label)}<span>${graph.nodes.filter(x=>x.group===n.group).length}</span></button>`).join('');$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.filter=state.filter===b.dataset.filter?null:b.dataset.filter;filterGraph();}));filterGraph();applyTransform();if(state.selected&&!graph.nodes.some(n=>n.id===state.selected)){state.selected=null;$('#detail-panel').hidden=true;}else if(state.selected&&!$('#detail-panel').hidden)showNode(state.selected);
}
function filterGraph(){$$('.graph-edge').forEach(e=>{const active=state.selected&&(e.dataset.source===state.selected||e.dataset.target===state.selected);e.classList.toggle('connected',Boolean(active));e.classList.toggle('unconnected',Boolean(state.selected&&!active));});$$('[data-group]',$('#network')).forEach(e=>e.style.opacity=!state.filter||e.dataset.group===state.filter||e.dataset.group==='location'?'1':'.13');$$('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===state.filter)));}
function showNode(id){const n=state.data.network.nodes.find(n=>n.id===id);if(!n)return;state.selected=id;filterGraph();$$('.graph-node').forEach(e=>e.classList.toggle('selected',e.dataset.id===id));$('#detail-panel').hidden=false;$('#detail-content').innerHTML=`<span class="eyebrow">${escapeHTML(labels[n.group]||'KARACHI PULSE')}</span><h2>${escapeHTML(n.label)}</h2>${n.value!==null?`<div class="node-metric"><strong>${escapeHTML(nodeValue(n))}</strong></div>`:''}${badge(n.status)}<p>${escapeHTML(n.description||'Select a connected signal to explore its current value and source.')}</p><div class="node-source"><span class="eyebrow">VALUE TIME · PKT</span><p>${date(n.time_utc)}</p><span class="eyebrow">SOURCE</span><p>${escapeHTML(n.source||'HeatSafe Pakistan project')}</p></div><button class="card-link" id="node-open-view">Explore ${escapeHTML(n.view==='air'?'air quality':n.view==='forecast'?'forecast':n.view==='evidence'?'sources':'overview')} ↗</button>`;$('#node-open-view').addEventListener('click',()=>showView(n.view));}
function applyTransform(){state.zoom=Math.max(.55,Math.min(2,state.zoom));$('#map-transform').setAttribute('transform',`translate(${705+state.pan.x} ${410+state.pan.y}) scale(${state.zoom}) translate(-705 -410)`);$('#zoom-reset').textContent=Math.round(state.zoom*100)+'%';}
function resetMap(){state.zoom=1;state.pan={x:0,y:0};applyTransform();}


async function ask(question){
 const requestCity=state.city;question=question.trim();if(!question||state.asking)return;state.asking=true;
 $('#answer-panel').hidden=false;$('#answer-content').innerHTML=`<div class="answer-question">${escapeHTML(question)}</div><div class="answer-text">Reading the city data and relevant evidence…</div>`;$('.send-button').disabled=true;
 try{
  const response=await fetch('/api/insight',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,city:requestCity,history:state.chatHistory.slice(-4).map(m=>({role:m.role,content:m.content.slice(0,1200)})),date_from:state.dateFrom,date_to:state.dateTo}),signal:AbortSignal.timeout(55000)});
  if(!response.headers.get('content-type')?.includes('application/json'))throw Error('offline');
  const result=await response.json();if(!response.ok||typeof result.answer!=='string')throw Error('unavailable');
  if(requestCity!==state.city)return;
  const citations=(result.citations||[]).map(c=>`<li>${typeof c.url==='string'&&c.url.startsWith('https://')?`<a href="${safeURL(c.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(c.title)}</a>`:escapeHTML(c.title)}</li>`).join('');
  const note=result.mode==='gemini'?'Gemini · grounded in project data and retrieved guidance. Check the cited evidence.':'AI connection unavailable · no generated answer.';
  $('#answer-content').innerHTML=`<div class="answer-question">${escapeHTML(question)}</div><div class="answer-text">${escapeHTML(result.answer)}</div>${result.context_note?`<div class="answer-note">${escapeHTML(result.context_note)}</div>`:''}${citations?`<ul class="answer-citations">${citations}</ul>`:''}<div class="answer-note">${note}</div><div class="suggestions"><button data-ask="What stands out in the weather and air quality?">Summarize conditions</button><button data-ask="Explain the prediction and its uncertainty in simple words.">Explain prediction</button><button data-ask="Which hours look cooler, and how does the air compare?">Help me plan</button><button id="clear-chat">New conversation</button></div>`;
  if(result.mode==='gemini'){state.chatHistory.push({role:'user',content:question},{role:'assistant',content:result.answer});state.chatHistory=state.chatHistory.slice(-4);}
  $$('[data-ask]').forEach(b=>b.addEventListener('click',()=>{$('#question').value=b.dataset.ask;ask(b.dataset.ask);}));
  $('#clear-chat').addEventListener('click',()=>{state.chatHistory=[];$('#answer-panel').hidden=true;$('#question').value='';});
 }catch{
  if(requestCity!==state.city)return;
  $('#answer-content').innerHTML=`<div class="answer-question">${escapeHTML(question)}</div><p class="answer-text">I couldn’t connect to the assistant just now. Please try again shortly. You can still explore the dashboard while the connection recovers.</p>`;
 }finally{state.asking=false;$('.send-button').disabled=false;}
}
function chooseTheme(theme){if(!['forest','maroon','orange','brown','purple'].includes(theme))theme='maroon';document.documentElement.dataset.theme=theme;try{localStorage.setItem('heatsafe-theme',theme);}catch{}$$('[data-theme-choice]').forEach(b=>b.classList.toggle('selected',b.dataset.themeChoice===theme));if(state.data)render();}
function init(){
 $('#city-select').addEventListener('change',()=>{state.city=$('#city-select').value;state.chatHistory=[];state.data=null;state.selected=null;state.filter=null;$('#answer-panel').hidden=true;$('#detail-panel').hidden=true;$('#network-view').hidden=true;$('#content-view').hidden=false;$('#content-view').innerHTML='<div class="loading-state"><h2>Loading city data…</h2></div>';$('#pulse-kpis').textContent='Loading selected city…';$('#city-title').textContent=$('#city-select').selectedOptions[0].textContent+' Pulse';$('#city-location').textContent='';loadData();});


 $$('[data-date-preset]').forEach(b=>b.addEventListener('click',()=>{const preset=b.dataset.datePreset;if(preset==='custom')openCalendar();else{const range=presetDates(preset);setDates(range.from,range.to,preset);}}));
 $('#date-reset').addEventListener('click',()=>setDates('','','outlook'));
 $('#calendar-prev').addEventListener('click',()=>moveCalendar(-1));$('#calendar-next').addEventListener('click',()=>moveCalendar(1));
 $('#calendar-cancel').addEventListener('click',()=>closeCalendar());
 $('#calendar-apply').addEventListener('click',()=>{if(state.draftStart&&state.draftEnd){setDates(state.draftStart,state.draftEnd);$('#custom-date-button').focus();}});
 document.addEventListener('click',e=>{if(!$('#range-calendar').hidden&&!e.composedPath().includes($('#range-calendar'))&&!$('#custom-date-button').contains(e.target))closeCalendar(false);});
 let theme='maroon';try{theme=localStorage.getItem('heatsafe-theme')||theme;}catch{}chooseTheme(theme);
 $$('.view-tab').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));$('#refresh-button').addEventListener('click',()=>loadData(true));$('#ask-form').addEventListener('submit',e=>{e.preventDefault();ask($('#question').value);});$('#close-answer').addEventListener('click',()=>$('#answer-panel').hidden=true);$('#close-detail').addEventListener('click',()=>{state.selected=null;$('#detail-panel').hidden=true;filterGraph();$$('.graph-node').forEach(e=>e.classList.remove('selected'));});
 $('#theme-button').addEventListener('click',()=>{const menu=$('#theme-menu');menu.hidden=!menu.hidden;$('#theme-button').setAttribute('aria-expanded',String(!menu.hidden));});$$('[data-theme-choice]').forEach(b=>b.addEventListener('click',()=>{chooseTheme(b.dataset.themeChoice);$('#theme-menu').hidden=true;$('#theme-button').setAttribute('aria-expanded','false');}));
 $('#help-button').addEventListener('click',()=>$('#info-dialog').showModal());$('#guide-button').addEventListener('click',()=>$('#info-dialog').showModal());$('.dialog-close').addEventListener('click',()=>$('#info-dialog').close());
 $('#zoom-in').addEventListener('click',()=>{state.zoom+=.15;applyTransform();});$('#zoom-out').addEventListener('click',()=>{state.zoom-=.15;applyTransform();});$('#zoom-reset').addEventListener('click',resetMap);$('#fit-map').addEventListener('click',resetMap);$('#network-layout').addEventListener('click',()=>{state.orbit=false;buildNetwork();});$('#orbit-layout').addEventListener('click',()=>{state.orbit=true;buildNetwork();});$('#motion-toggle').addEventListener('click',()=>{state.paused=!state.paused;document.body.classList.toggle('motion-paused',state.paused);$('#motion-toggle').setAttribute('aria-pressed',String(state.paused));$('#motion-toggle').textContent=state.paused?'▷':'Ⅱ';});document.body.classList.toggle('motion-paused',state.paused);
 const network=$('#network');let drag=null;network.addEventListener('wheel',e=>{e.preventDefault();state.zoom+=e.deltaY>0?-.07:.07;applyTransform();},{passive:false});network.addEventListener('pointerdown',e=>{if(e.target.closest('.graph-node'))return;drag={x:e.clientX,y:e.clientY,pan:{...state.pan}};network.setPointerCapture(e.pointerId);network.classList.add('dragging');});network.addEventListener('pointermove',e=>{if(!drag)return;const ratio=1440/network.getBoundingClientRect().width;state.pan={x:drag.pan.x+(e.clientX-drag.x)*ratio,y:drag.pan.y+(e.clientY-drag.y)*ratio};applyTransform();});['pointerup','pointercancel'].forEach(name=>network.addEventListener(name,()=>{drag=null;network.classList.remove('dragging');}));
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#range-calendar').hidden)closeCalendar();$('#answer-panel').hidden=true;$('#theme-menu').hidden=true;$('#theme-button').setAttribute('aria-expanded','false');$('#detail-panel').hidden=true;state.selected=null;filterGraph();$$('.graph-node').forEach(e=>e.classList.remove('selected'));}});
 setInterval(()=>{if(!document.hidden)loadData();},300000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&Date.now()-(state.lastLoad||0)>300000)loadData();});loadData();
}
if(typeof document!=='undefined')init();
else if(typeof module!=='undefined')module.exports={finite,fmt,nodeValue,weatherInfo,rowsForWindow,joinAir,segments,graphPositions,escapeHTML,calendarDay,filterDates,extreme,connectedLinks,forecastRows,presetDates,dayNumber,dayString,rollingRows,calendarCells,pickRange};
